import { useEffect, useRef } from 'react';

import { OpenFin } from '@openfin/core';

import { connectToEnterpriseContentChannel } from '@common/utils/enterprise-channels';
import { createLogger } from '@common/utils/logger';

import { getCurrentSync } from '@client-platform/api';

const logger = createLogger('enterprise.useAsyncResultsObserver');
import { SearchProviderResult } from '@client-platform/shapes';
import { AsyncResultsObserver } from '@enterprise/hooks/EnterpriseSearchMenu/utils';

/*
 * useAsyncResultsObserver is a hook that listens for search results from the enterprise content channel.
 * It returns an object with on and off methods to add and remove listeners for search results.
 */
export const useAsyncResultsObserver = (): AsyncResultsObserver => {
    const contentChannel = useRef<OpenFin.ChannelClient | null>(null);
    const callbacksRef = useRef<Set<(payload: SearchProviderResult) => void>>(new Set());

    const observerRef = useRef<AsyncResultsObserver>({
        on: (callback: (payload: SearchProviderResult) => void) => {
            callbacksRef.current.add(callback);
        },
        off: (callback: (payload: SearchProviderResult) => void) => {
            callbacksRef.current.delete(callback);
        }
    });

    useEffect(() => {
        let isMounted = true;

        const initializeChannel = async () => {
            try {
                const platform = getCurrentSync();
                contentChannel.current = await connectToEnterpriseContentChannel(platform.identity.uuid);

                if (!isMounted) return;

                contentChannel.current.register('search-results-async', (payload: SearchProviderResult) => {
                    callbacksRef.current.forEach((callback) => callback(payload));
                });
            } catch (error) {
                logger.error('initializeChannel', 'Failed to connect to the enterprise content channel', {
                    error: error instanceof Error ? error.message : String(error)
                });
            }
        };

        initializeChannel();

        return () => {
            isMounted = false;
            if (contentChannel.current) {
                contentChannel.current.remove('search-results-async');
                contentChannel.current = null;
            }
        };
    }, []);

    return observerRef.current;
};
