import { useContext } from 'react';

import styled from 'styled-components';

import { Icon } from '@openfin/ui-library';

import { SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';

import { CommandBar } from './CommandBar';
import { ContentContainer, EMPTY_SEARCH_INPUT_CONTAINER_ID } from './EmptySearchInputContainer';

const EmptySingleProviderSearchContainer = ({ providerId }: { providerId: string }) => {
    const { searchProviders } = useContext(SearchResultsContext);
    const activeProvider = searchProviders.find((p) => p.id === providerId);

    return (
        <div id={EMPTY_SEARCH_INPUT_CONTAINER_ID}>
            <ContentContainer>
                <Container>
                    {activeProvider?.icon ? (
                        <ProviderIcon src={activeProvider.icon} alt={activeProvider.title} />
                    ) : (
                        <LargeIcon icon="MagnifyingGlassIcon" size="xxxlarge" />
                    )}
                    <TextSection>
                        <HeaderText>Search {activeProvider.title}</HeaderText>
                        <Subtext className="search-empty-single-provider-subtext">Start typing to see results.</Subtext>
                    </TextSection>
                </Container>
            </ContentContainer>
            <CommandBar />
        </div>
    );
};

export default EmptySingleProviderSearchContainer;

const Container = styled.div`
    height: 184px;

    display: flex;
    gap: ${({ theme }) => theme.px.large};
    flex-direction: column;
    align-items: center;
    justify-content: center;
`;

const TextSection = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
`;

const ProviderIcon = styled.img`
    height: 64px;
    width: 64px;
    border-radius: ${({ theme }) => theme.px.small};
`;

const HeaderText = styled.span`
    height: ${({ theme }) => theme.px.xxlarge};
    font-size: ${({ theme }) => theme.fontSize.large};
    font-weight: 500;
`;

const Subtext = styled.span`
    color: var(--color-enterprise-search-menu-text-soft);
    text-align: center;
`;

const LargeIcon = styled(Icon)`
    --px-container: 64px;
    --px-icon: 64px;
`;
