import { useCallback, useEffect, useState } from 'react';

import { createLogger } from '@common/utils/logger';
import { SearchProviderResult, SearchSitesResponse } from '@client-platform/shapes';
import { AsyncResultsObserver } from '@enterprise/hooks/EnterpriseSearchMenu/utils';

const logger = createLogger('enterprise.useAsyncProviderResults');

/**
 * Custom hook to manage asynchronous search results.
 *
 * @param {SearchSitesResponse} searchResults - The initial search results to set.
 * @param {AsyncResultsObserver} asyncResultsObserver - The observer to handle updates from the search provider.
 * @param {string} queryId - The unique identifier for the current query.
 * @returns {SearchSitesResponse} The current state of asynchronous search results.
 */
export const useAsyncProviderResults = (
    searchResults: SearchSitesResponse,
    asyncResultsObserver: AsyncResultsObserver,
    queryId: string
) => {
    const [asyncSearchResults, setAsyncSearchResults] = useState<SearchSitesResponse>([]);

    // Reset async results when queryId changes (new query started)
    useEffect(() => {
        logger.debug('onQueryIdChange', 'New query received', { queryId });
        setAsyncSearchResults([]);
    }, [queryId]);

    useEffect(() => {
        logger.debug('onSearchResults', 'Initial search results received', {
            queryId,
            providersCount: searchResults.length,
            providers: searchResults.map((r) => ({
                id: r.id,
                hasResults: r.results !== null && r.results !== undefined,
                resultsCount: r.results?.length
            }))
        });

        // Merge incoming search results with any providers already added via async messages
        setAsyncSearchResults((prev) => {
            // If we have no previous state, just use the new results
            if (prev.length === 0) {
                return searchResults;
            }

            const merged = searchResults.map((incoming) => {
                const existing = prev.find((p) => p.id === incoming.id);

                if (existing && existing.results !== null && existing.results !== undefined) {
                    return existing;
                }

                return incoming;
            });

            // Add any async-only providers (shouldn't happen if all providers are known beforehand)
            const incomingIds = new Set(searchResults.map((r) => r.id));
            const asyncOnlyProviders = prev.filter((p) => !incomingIds.has(p.id));

            return [...merged, ...asyncOnlyProviders];
        });
    }, [searchResults, queryId]);

    const updateHandler = useCallback(
        (providerResult: SearchProviderResult) => {
            if (providerResult.queryId !== queryId) {
                logger.debug('onAsyncResult', 'Ignoring stale async results', {
                    providerId: providerResult.id,
                    currentQueryId: queryId,
                    messageQueryId: providerResult.queryId
                });
                return;
            }

            logger.debug('onAsyncResult', 'Async results received', {
                providerId: providerResult.id,
                queryId: providerResult.queryId,
                resultsCount: providerResult.results?.length
            });

            setAsyncSearchResults((prev) => {
                const existsInArray = prev.some((result) => result.id === providerResult.id);

                if (existsInArray) {
                    // Update existing provider
                    return prev.map((result) => {
                        if (result.id === providerResult.id) {
                            return {
                                ...result,
                                results: providerResult.results,
                                showViewMore: providerResult.showViewMore
                            };
                        }
                        return result;
                    });
                } else {
                    // Add provider that arrived via async before initial state was populated
                    return [
                        ...prev,
                        {
                            id: providerResult.id,
                            results: providerResult.results,
                            showViewMore: providerResult.showViewMore
                        }
                    ];
                }
            });
        },
        [queryId]
    );

    useEffect(() => {
        asyncResultsObserver.on(updateHandler);
        return () => {
            asyncResultsObserver.off(updateHandler);
        };
    }, [asyncResultsObserver, updateHandler]);

    return asyncSearchResults;
};
