import React, { useContext } from 'react';

import styled from 'styled-components';

import { NoResults } from '@enterprise/components/ControlBar/SearchMenu/NoResults';
import { Result } from '@enterprise/components/ControlBar/SearchMenu/Result';
import { ResultsContainerWrapper } from '@enterprise/components/ControlBar/SearchMenu/ResultsContainerWrapper';
import { SkeletonResultList } from '@enterprise/components/ControlBar/SearchMenu/SkeletonResult';
import { useLazyLoading } from '@enterprise/components/ControlBar/SearchMenu/useLazyLoading';

import { SearchProvider, SearchProviderResult } from '@client-platform/shapes';
import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';
import { SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';

import { FilterButtons } from './FilterButtons';
import { useSingleProviderAnnounceMessages } from './useSingleProviderAnnounceMessages';

export interface SingleProviderResultsContainerProps {
    providerResults: SearchProviderResult;
}

export const SingleProviderResultsContainer = ({ providerResults }: SingleProviderResultsContainerProps) => {
    const { isQueryingResults, searchProviders, setAction } = useContext(SearchResultsContext);
    const { searchQuery, queryId } = useContext(SearchMenuControlContext);
    const activeProvider: SearchProvider | undefined = searchProviders.find(
        (provider) => provider.id === providerResults.id
    );
    const lazyLoading = useLazyLoading(providerResults, searchQuery.current, queryId, !activeProvider?.supportsPaging);
    const isLoading = lazyLoading?.isLoading || isQueryingResults || !providerResults?.results;

    useSingleProviderAnnounceMessages(providerResults, activeProvider, lazyLoading);

    return (
        <>
            {activeProvider?.filters?.length > 0 ? (
                <FilterButtons provider={activeProvider} />
            ) : (
                <Padding className="search-results-padding" />
            )}
            <ResultsContainerWrapper flattenedResults={lazyLoading?.providerResults ?? []} isLoading={isLoading}>
                {(setFocused, focused, onSiteAction) => (
                    <>
                        {!isLoading && lazyLoading?.providerResults?.length === 0 && (
                            <NoResults provider={activeProvider} />
                        )}
                        {lazyLoading?.providerResults?.map((site) => (
                            <React.Fragment key={`${providerResults.id}-results-${site.type}-${site.id}`}>
                                <Result
                                    site={site}
                                    isFocused={site === focused}
                                    id={`result-${site.type}-${site.id}`}
                                    onSiteAction={onSiteAction}
                                    onFocused={setFocused}
                                    updateAction={setAction}
                                />
                            </React.Fragment>
                        ))}
                        {isLoading && <SkeletonResultList resultsNum={5} />}
                    </>
                )}
            </ResultsContainerWrapper>
        </>
    );
};

const Padding = styled.div`
    height: ${({ theme }) => theme.px.small};

    border-right: 1px solid var(--color-enterprise-search-menu-border);
    border-left: 1px solid var(--color-enterprise-search-menu-border);
`;
