import { useCallback, useEffect, useReducer, useRef } from 'react';

import { createLogger } from '@common/utils/logger';

import { SearchProviderResult } from '@client-platform/shapes';
import { searchSites } from '@enterprise/hooks/EnterpriseSearchMenu/utils';

const logger = createLogger('enterprise.useLazyLoading');

type LazyLoadingState = {
    currentProviderId?: string;
    isLoading: boolean;
    providerResults?: SearchProviderResult['results'];
    pageNumber?: number;
    pageSize?: number;
    lastQueryResultsLength?: number;
};

type LazyLoadingAction =
    | { type: 'INITIALIZE'; payload: LazyLoadingState }
    | { type: 'SET_LOADING'; payload: boolean }
    | {
          type: 'LOAD_MORE_SUCCESS';
          payload: { results: SearchProviderResult['results']; pageNumber: number; lastQueryResultsLength: number };
      }
    | { type: 'LOAD_MORE_FAILURE' }
    | { type: 'LOAD_MORE_NO_MORE' };

const initialState: LazyLoadingState = {
    isLoading: false
};

const lazyLoadingReducer = (state: LazyLoadingState, action: LazyLoadingAction): LazyLoadingState => {
    switch (action.type) {
        case 'INITIALIZE':
            return { ...state, ...action.payload };
        case 'SET_LOADING':
            return { ...state, isLoading: action.payload };
        case 'LOAD_MORE_SUCCESS':
            return {
                ...state,
                isLoading: false,
                providerResults: [...(state.providerResults || []), ...action.payload.results],
                pageNumber: action.payload.pageNumber,
                lastQueryResultsLength: action.payload.lastQueryResultsLength
            };
        case 'LOAD_MORE_FAILURE':
            return { ...state, isLoading: false };
        case 'LOAD_MORE_NO_MORE':
            return { ...state, isLoading: false, lastQueryResultsLength: 0 };
        default:
            return state;
    }
};

/**
 * A custom hook for implementing lazy loading of search results.
 * This hook manages the loading state, handles pagination, and integrates with an IntersectionObserver
 * to load more results as the user scrolls.
 *
 * @param searchProviderResults - The results from the search provider.
 * @param searchQuery - The search query string used for fetching results.
 * @param queryId - A unique identifier for the current query session.
 * @param disabled - A flag to disable the lazy loading functionality.
 * @returns LazyLoadingState - The current state of the lazy loading, including loading status, provider results, and pagination information.
 */
export const useLazyLoading = (
    searchProviderResults: SearchProviderResult,
    searchQuery: string,
    queryId: string,
    disabled: boolean
) => {
    const [state, dispatch] = useReducer(lazyLoadingReducer, initialState);

    /**
     * This `requestId` keeps track of which "session" of requests we are on.
     * Any time you re-initialize, bump this value to effectively cancel in-flight requests for the lazy load.
     */
    const requestIdRef = useRef(0);

    const observer = useRef<IntersectionObserver | null>(null);

    const loadNextPage = useCallback(async () => {
        // Capture the current request ID at the start of the load operation
        const currentRequestId = requestIdRef.current;

        dispatch({ type: 'SET_LOADING', payload: true });
        const newPage = (state.pageNumber || 1) + 1;

        try {
            const response = await searchSites({
                providerId: state.currentProviderId!, // we know it's set after INITIALIZE
                queryId: queryId,
                query: searchQuery,
                pageNumber: newPage
            });

            // Compare the local requestId to the most up-to-date value in the ref
            // to check if we've been invalidated.
            if (currentRequestId !== requestIdRef.current) {
                // Request is "old" => skip
                return;
            }

            const moreProviderResults = response.find((r) => r.id === state.currentProviderId);

            if (moreProviderResults && moreProviderResults.results.length > 0) {
                logger.debug('loadNextPage', 'Lazy load next page success', {
                    providerId: state.currentProviderId,
                    pageNumber: newPage,
                    resultsCount: moreProviderResults.results.length
                });

                dispatch({
                    type: 'LOAD_MORE_SUCCESS',
                    payload: {
                        results: moreProviderResults.results,
                        pageNumber: newPage,
                        lastQueryResultsLength: moreProviderResults.results.length
                    }
                });
            } else {
                logger.debug('loadNextPage', 'No more results available', {
                    providerId: state.currentProviderId,
                    pageNumber: newPage
                });

                dispatch({ type: 'LOAD_MORE_NO_MORE' });
            }
        } catch (error) {
            logger.error('loadNextPage', 'Error loading next page', {
                error: error instanceof Error ? error.message : String(error)
            });

            // Check again in case we were invalidated during the fetch
            if (currentRequestId !== requestIdRef.current) {
                return;
            }
            dispatch({ type: 'LOAD_MORE_FAILURE' });
        }
    }, [searchQuery, state.currentProviderId, state.pageNumber, queryId]);

    useEffect(() => {
        if (searchProviderResults) {
            // Increment the ref to invalidate any in-flight requests
            requestIdRef.current += 1;

            logger.debug('onSearchProviderResults', 'Single provider results received', {
                providerId: searchProviderResults.id,
                resultsCount: searchProviderResults.results?.length || 0,
                pageNumber: searchProviderResults.pageNumber || 1,
                pageSize: searchProviderResults.pageSize
            });

            dispatch({
                type: 'INITIALIZE',
                payload: {
                    currentProviderId: searchProviderResults.id,
                    isLoading: false,
                    providerResults: searchProviderResults.results,
                    pageNumber: searchProviderResults.pageNumber || 1,
                    pageSize: searchProviderResults.pageSize,
                    lastQueryResultsLength: searchProviderResults.results?.length || 0
                }
            });
        } else {
            dispatch({ type: 'SET_LOADING', payload: true });
        }
    }, [searchProviderResults]);

    useEffect(() => {
        if (!state.providerResults || state.providerResults.length === 0) return;
        if (disabled) return;

        if (observer.current) {
            observer.current.disconnect();
            observer.current = null;
        }

        const lastSite = state.providerResults[state.providerResults.length - 1];
        const lastSiteElementId = `result-${lastSite.type}-${lastSite.id}`;
        const lastSiteElement = document.getElementById(lastSiteElementId);

        if (!lastSiteElement) return;

        const handleObserver = async (entries: IntersectionObserverEntry[]) => {
            const [entry] = entries;

            const canLoad = !state.isLoading && state.lastQueryResultsLength === state.pageSize;

            if (entry.isIntersecting && canLoad) {
                observer.current?.disconnect();
                observer.current = null;
                await loadNextPage();
            }
        };

        observer.current = new IntersectionObserver(handleObserver, { root: null, threshold: 1.0 });
        observer.current.observe(lastSiteElement);

        return () => {
            observer.current?.disconnect();
        };
    }, [state.providerResults, state.isLoading, state.lastQueryResultsLength, state.pageSize, loadNextPage, disabled]);

    return state;
};
