import { useCallback, useEffect, useRef } from 'react';

import { SearchMenuChannelResponse } from '@common/utils/popup-window';
import { SelectableResult } from '@common/utils/popup-window';

/**
 * Custom hook that returns functions to post announcement messages to the browser window.
 * Uses the provided searchMenuChannel for communication.
 *
 * @param searchMenuChannel - Reference to the BroadcastChannel used for communication
 * @returns Object containing:
 *   - postFocusedChangedAnnouncement: Function to post focused-changed messages
 *   - postAllProvidersAnnouncement: Function to post all-providers announcement messages
 *   - postSingleProviderAnnouncement: Function to post single-provider announcement messages
 */
export const usePostAnnounceMessagesToBrowserWindow = (
    searchMenuChannel: React.MutableRefObject<BroadcastChannel | undefined>
) => {
    const previousFocusedIdRef = useRef<string | null>(null);
    const previousAllProvidersMessageRef = useRef<string>('');
    const previousSingleProviderMessageRef = useRef<string>('');

    const postFocusedChangedAnnouncement = useCallback(
        (focused: SelectableResult | null) => {
            if (focused && focused.id !== previousFocusedIdRef.current && searchMenuChannel.current) {
                searchMenuChannel.current.postMessage({
                    type: 'focused-changed',
                    payload: focused
                } as SearchMenuChannelResponse);
                previousFocusedIdRef.current = focused.id;
            } else if (!focused) {
                previousFocusedIdRef.current = null;
            }
        },
        [searchMenuChannel]
    );

    const postAllProvidersAnnouncement = useCallback(
        (message: string) => {
            // Only post if message is different from previous
            if (message && message !== previousAllProvidersMessageRef.current && searchMenuChannel.current) {
                searchMenuChannel.current.postMessage({
                    type: 'all-providers-results-announcement',
                    message
                } as SearchMenuChannelResponse);
                previousAllProvidersMessageRef.current = message;
            }
        },
        [searchMenuChannel]
    );

    const postSingleProviderAnnouncement = useCallback(
        (message: string) => {
            // Only post if message is different from previous
            if (message && message !== previousSingleProviderMessageRef.current && searchMenuChannel.current) {
                searchMenuChannel.current.postMessage({
                    type: 'single-provider-results-announcement',
                    message
                } as SearchMenuChannelResponse);
                previousSingleProviderMessageRef.current = message;
            }
        },
        [searchMenuChannel]
    );

    // Cleanup refs on unmount
    useEffect(() => {
        return () => {
            previousFocusedIdRef.current = null;
            previousAllProvidersMessageRef.current = '';
            previousSingleProviderMessageRef.current = '';
        };
    }, []);

    return { postFocusedChangedAnnouncement, postAllProvidersAnnouncement, postSingleProviderAnnouncement };
};
