import { createContext, Dispatch, SetStateAction, useMemo, useState } from 'react';

import { useCuratedContent } from '@enterprise/components/LandingPage/useCuratedContent';

import { SearchProvider, SearchSitesResponse, Site } from '@client-platform/shapes';
import { SiteAction } from '@client-platform/shapes';

export const DEFAULT_ALL_TAB = { id: '0', title: 'All' };

const defaultFunction = () => {
    return;
};

export const emptySearchResults: SearchSitesResponse = [];

/**
 * Represents the selected state of search filters.
 */
type SearchMenuFilters = string[];

interface SearchResultsContextType {
    recentlyVisited: Site[];
    setRecentlyVisited: Dispatch<SetStateAction<Site[]>>;
    curatedContent: Site[];
    searchResults: SearchSitesResponse;
    setSearchResults: Dispatch<SetStateAction<SearchSitesResponse>>;
    isQueryingResults: boolean;
    setIsQueryingResults: Dispatch<SetStateAction<boolean>>;
    activeProviderId: string;
    setActiveProviderId: Dispatch<SetStateAction<string>>;
    searchProviders: SearchProvider[];
    setSearchProviders: Dispatch<SetStateAction<SearchProvider[]>>;
    action: SiteAction;
    setAction: Dispatch<SetStateAction<SiteAction>>;
    filters: SearchMenuFilters;
    setFilters: Dispatch<SetStateAction<SearchMenuFilters>>;
}

export const SearchResultsContext = createContext<SearchResultsContextType>({
    recentlyVisited: [],
    setRecentlyVisited: defaultFunction,
    curatedContent: [],
    searchResults: emptySearchResults,
    setSearchResults: defaultFunction,
    isQueryingResults: false,
    setIsQueryingResults: defaultFunction,
    activeProviderId: DEFAULT_ALL_TAB.id,
    setActiveProviderId: defaultFunction,
    searchProviders: [],
    setSearchProviders: defaultFunction,
    action: null,
    setAction: defaultFunction,
    filters: [],
    setFilters: defaultFunction
});

export const SearchResultsContextProvider = ({ children }: { children?: React.ReactNode }) => {
    const [recentlyVisited, setRecentlyVisited] = useState<Site[]>([]);
    const [curatedContent] = useCuratedContent();

    const [searchResults, setSearchResults] = useState<SearchSitesResponse>(emptySearchResults);
    const [isQueryingResults, setIsQueryingResults] = useState<boolean>(false);
    const [activeProviderId, setActiveProviderId] = useState(DEFAULT_ALL_TAB.id);
    const [searchProviders, setSearchProviders] = useState<SearchProvider[]>([]);
    const [action, setAction] = useState<SiteAction>(null);
    const [filters, setFilters] = useState<SearchMenuFilters>([]);

    const value = useMemo(
        () => ({
            recentlyVisited,
            setRecentlyVisited,
            curatedContent,
            searchResults,
            setSearchResults,
            isQueryingResults,
            setIsQueryingResults,
            activeProviderId,
            setActiveProviderId,
            searchProviders,
            setSearchProviders,
            action,
            setAction,
            filters,
            setFilters
        }),
        [
            recentlyVisited,
            curatedContent,
            searchResults,
            isQueryingResults,
            activeProviderId,
            searchProviders,
            action,
            filters
        ]
    );

    return <SearchResultsContext.Provider value={value}>{children}</SearchResultsContext.Provider>;
};
